\begin{theorem}\label{reverse_loomis_zonoids}
    Let $\mathbb{S}=(S,\sigma,v)$ a generalised $d$-hypersurface. There exists an orthonormal basis $\{w_i\}_{i=1}^{d}$ of $\mathbb{R}^d$ such that for any $1$-uniform cover $(\sigma_1,\dots, \sigma_m)$ of $[d]$ and $E_i = span\{w_j : j\in\sigma_i\}$ we have
     \begin{equation}
    \prod_{j=1}^m|P_{E_j}(\Pi(\mathbb{S}))|\le\frac{(\sqrt{d})^{d}}{\prod_{j=1}^m\sqrt{d_j!}}|\Pi(\mathbb{S})|.
     \end{equation}
\end{theorem}

ref_dict.cont_brascamp_lieb:
\begin{theorem}[Continuous Brascamp--Lieb on $S$]\label{cont_brascamp_lieb}
Let $S$ be a hypersurface equipped with a positive measure $\mu$.
Let $v:S\to\mathbb{R}^n$ be measurable with $v(x)\neq0$ for $\mu$‑almost every $x\in S$, and assume the normalization
\begin{equation}\label{eq:identity_assumption}
I_d= \int_S \frac{v(x)\otimes v(x)}{\|v(x)\|_2^2}\,d\mu(x).
\end{equation}
Define the unit directions $u(x):=v(x)/\|v(x)\|_2\in S^{n-1}$ and suppose we are given a measurable family
of non-negative functions ${f_x:\mathbb R\to[0,\infty)},{x\in S}$ that meets the usual technical integrability
conditions.

Then the following inequality holds:
\begin{equation}\label{eq:conclusion_S}
\int_{\mathbb R^n}\exp\Big(\int_S\log\bigl(f_x(\langle y,u(x)\rangle)\bigr)\,d\mu(x)\Big)\,dy
\le
\exp\Big(\int_S\log\Big(\int_{\mathbb R} f_x(t)\,dt\Big)\, d\mu(x)\Big).
\end{equation}
\end{theorem}

