\begin{thm}[Equidistribution of expanding translate of shirinking  pieces of a curve]\label{Thm : 1. shrinking equidistribuiton at point}
    Let the notation and conditions be as in Theorem~\ref{Theorem : 1. main theorem}.
    Then, there exists a Lebesgue null set $E$ in $I$ such that for $m: = \frac{\zeta_k}{2}$ and for any $s_0 \in I\backslash E$, $f \in C_c(X)$, a sequence $\{s_n\}_{n \in \N}$ in $I$ and a sequence $\{t_n\}_{n \in\N}$ in $\R$ such that $s_n \to s_0$ and $t_n \to \infty $ as $n \to \infty$, we have
    \begin{equation}\label{equation: 1. equidist on shrinking curve}
        \lim_{n \to \infty}\int^1_0 f\big(a(t_n)\psi(s_n + e^{-mt_n}\eta)x_0\big) \, d\eta = \int_X f d\mu_L.
    \end{equation}
\end{thm}

